grant insert(name,kind,active),update(name,kind,active) on public.studio_resources to authenticated; create policy resource_admin_insert on public.studio_resources for insert to authenticated with check(exists(select 1 from public.studio_admin_memberships where user_id=(select auth.uid())) and char_length(trim(name)) between 1 and 120); create policy resource_admin_update on public.studio_resources for update to authenticated using(exists(select 1 from public.studio_admin_memberships where user_id=(select auth.uid()))) with check(exists(select 1 from public.studio_admin_memberships where user_id=(select auth.uid())) and char_length(trim(name)) between 1 and 120);
